css:
/* A4 landscape: the day grid needs the width. The PDF button reads orientation from .print-format. */
@page { size: A4 landscape; margin: 8mm; }
.print-format { orientation: Landscape; }
@media screen { .print-format { max-width: 11.69in; min-height: 8.27in; padding: 0.3in; } }
.eims-month { direction: rtl; text-align: right; font-family: Tahoma, Arial, sans-serif; font-size: 12px; color: #000; }
.eims-month .school { text-align: center; font-size: 17px; font-weight: bold; }
.eims-month .title { text-align: center; font-size: 14px; font-weight: bold; margin: 2px 0; }
.eims-month .title span { margin: 0 24px; }
.eims-month .meta { display: flex; justify-content: space-between; align-items: center; font-weight: bold; margin: 6px 0 4px; }
.eims-month .box { border: 1px solid #000; padding: 3px 12px; min-width: 190px; }
.eims-month table { width: 100%; border-collapse: collapse; table-layout: fixed; }
/* Frappe pads every cell 6px !important; the grid needs them tight. */
.eims-month th, .eims-month td { border: 1px solid #000; height: 26px; padding: 0 2px !important; vertical-align: middle !important; text-align: center; }
.eims-month th { font-size: 10px; font-weight: bold; color: #000; }
.eims-month thead { display: table-header-group; }
.eims-month tr { page-break-inside: avoid; }
.eims-month .c-num { width: 26px; }
.eims-month .c-name { width: 23%; text-align: right; font-size: 11px; line-height: 1.2; }
.eims-month .off { background: #bbb !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }

html:
{%- set rows = frappe.get_all('EIMS Institution', fields=['institution_name'], limit=1) -%}
{%- set inst = rows[0] if rows else {} -%}
{%- set month = frappe.utils.getdate(doc.attendance_date) -%}
{%- set days = frappe.utils.get_last_day(month).day -%}
{%- set month_names = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'] -%}
{%- set group = frappe.db.get_value('EIMS Section', doc.section, 'name_ar') -%}
{%- set teacher = frappe.db.get_value('EIMS Staff', doc.teacher, 'name_ar') if doc.teacher else '' -%}
{#- The enrolled roster, plus anyone already recorded on the sheet who has since left. -#}
{%- set enrolled = frappe.get_all('EIMS Enrollment', filters={'section': doc.section, 'academic_year': doc.academic_year, 'status': 'مسجل', 'docstatus': ['<', 2]}, pluck='student') -%}
{%- set ids = (enrolled + doc.rows|map(attribute='student')|list)|unique|list -%}
{%- set students = frappe.get_all('EIMS Student', filters={'name': ['in', ids or ['']]}, fields=['name', 'student_name'], order_by='student_name asc') -%}
{#- Friday and Saturday are the school's days off; weekday() counts from Monday = 0. -#}
{%- set off = [] -%}
{%- for d in range(days) %}{% if frappe.utils.add_days(month, d).weekday() in (4, 5) %}{% set _ = off.append(d + 1) %}{% endif %}{% endfor -%}
<div class="eims-month">
	<div class="school">{{ inst.institution_name or '' }}</div>
	<div class="title">
		<span>كشف حضور وغياب للعام الدراسي {{ doc.academic_year or '' }} م</span>
		<span>الصف الدراسي : {{ doc.stage or '' }}</span>
	</div>
	<div class="title">شهر : {{ month_names[month.month - 1] }} ({{ '%02d' % month.month }})</div>

	<div class="meta">
		<span class="box">معلم الفصل : {{ teacher or doc.teacher or '' }}</span>
		<span>{% if group %}المجموعة ({{ group }}){% endif %}</span>
		<span>عدد الطلبة = {{ students|length }}</span>
	</div>

	<table>
		<thead><tr>
			<th class="c-num">ت</th>
			<th class="c-name">اسم الطالب</th>
			{%- for d in range(1, days + 1) %}
			<th class="{{ 'off' if d in off }}">{{ d }}</th>
			{%- endfor %}
		</tr></thead>
		<tbody>
		{%- for student in students %}
			<tr>
				<td class="c-num">{{ loop.index }}</td>
				<td class="c-name">{{ student.student_name or student.name }}</td>
				{%- for d in range(1, days + 1) %}
				<td class="{{ 'off' if d in off }}"></td>
				{%- endfor %}
			</tr>
		{%- endfor %}
		</tbody>
	</table>
</div>
